.metric {
  padding: 1rem;
  background: var(--surface-soft);
  border-radius: 12px;
}
.metric span { color: var(--text-secondary); font-size: 0.8rem; }
.metric strong { display: block; margin-top: 0.35rem; font-size: 1.2rem; }

.mock-schedule {
  background: #0f1830;
  border-radius: 12px;
