  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
}
.faq-content { max-height: 0; overflow: hidden; transition: max-height 0.25s; color: var(--text-secondary); }
.faq-item.active .faq-content { max-height: 120px; padding-bottom: 1rem; }

.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; }
.field { display: grid; gap: 0.4rem; }
.field.full { grid-column: 1 / -1; }
